// ShaderToy code: Moiré pattern with proper CRT emulation and animation
void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    // Normalize coordinates to [0, 1]
    vec2 uv = fragCoord / iResolution.xy;

    // Center coordinates
    uv -= 0.5;

    // Aspect ratio correction
    uv.x *= iResolution.x / iResolution.y;

    // Animate the circle centers using iTime
    float time = iTime * .5; // Slow down the animation
    vec2 center1 = vec2(sin(time), tan(time)) * 0.2; // Moving center 1
    vec2 center2 = vec2(tan(time), sin(time)) * 0.2; // Moving center 2

    // Create two sets of concentric circles
    float radius1 = length(uv - center1); // First circle center
    float radius2 = length(uv - center2); // Second circle center

    // Frequency of the circles (animated)
    float frequency = 20.0 + 10.0 * sin(iTime * 1.1);

    // Create the patterns
    float pattern1 = sin(radius1 * frequency * 6.2831);
    float pattern2 = sin(radius2 * frequency * 6.2831);

    // Combine the patterns to create Moiré effect
    float moire = pattern1 * pattern2;

    // CRT emulation effects
    vec2 crtUV = uv * 0.5 + 0.5; // Rescale to [0, 1] for CRT effect

    // Scanlines (vertical lines)
    float scanline = sin(crtUV.y * iResolution.y * 3.14159 * 2.0) * 0.1 + 1.0;

    // Vignette (darken edges)
    float vignette = 1.0 - length(uv) * 0.5;

    // Distortion (warping effect)
    float distortion = sin(crtUV.y * 3.14159 * 4.0 + iTime * 10.0) * 0.02;
    crtUV.x /= distortion*30.;

    // Apply CRT effects to the Moiré pattern
    moire *= scanline*1.4 * vignette;

    // Sample the Moiré pattern with distortion
    float distortedMoire = sin(length(crtUV - 0.5) * frequency * 6.2831);

    // Combine the original Moiré pattern with the distorted version
    moire = mix(moire, distortedMoire, 0.5);

    // Colorize the Moiré pattern
    vec3 color = vec3(moire * 0.5 + 0.5, moire * 0.2 + 0.5, moire * 0.8 + 0.2);

    // Output the final color
    fragColor = vec4(color, 1.0);
}
